import{_ as a,o,c as t,ag as r}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/docs-editor/page-layout-page-setup.png",s="/docs/images/docs-editor/page-layout-footer.png",m=JSON.parse(`{"title":"Set up pages, headers, and footers","description":"Set a doc's paper size, orientation, and margins, insert page breaks and horizontal lines, and add headers, footers, and page numbers.","frontmatter":{"title":"Set up pages, headers, and footers","description":"Set a doc's paper size, orientation, and margins, insert page breaks and horizontal lines, and add headers, footers, and page numbers.","type":"how-to"},"headers":[],"relativePath":"docs-editor/page-layout.md","filePath":"docs-editor/page-layout.md"}`),i={name:"docs-editor/page-layout.md"};function l(d,e,h,g,p,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="set-up-pages-headers-and-footers" tabindex="-1">Set up pages, headers, and footers <a class="header-anchor" href="#set-up-pages-headers-and-footers" aria-label="Permalink to &quot;Set up pages, headers, and footers&quot;">​</a></h1><p>Set up the pages of a doc and add text that repeats on every page. A new document uses Letter paper, portrait, with 1-inch margins. What you see on screen is how the pages print and export to PDF.</p><h2 id="change-paper-size-and-orientation" tabindex="-1">Change paper size and orientation <a class="header-anchor" href="#change-paper-size-and-orientation" aria-label="Permalink to &quot;Change paper size and orientation&quot;">​</a></h2><ol><li>Click <strong>Page setup</strong> (page icon) at the right end of the toolbar.</li><li>Under <strong>Paper size</strong>, select <strong>Letter</strong>, <strong>A4</strong>, or <strong>Legal</strong>.</li><li>Under <strong>Orientation</strong>, select <strong>Portrait</strong> or <strong>Landscape</strong>.</li><li>Click <strong>Apply</strong>.</li></ol><p>The change applies to every page, and one undo reverts it. A Word file with another paper size shows it as <strong>Custom (name)</strong>; pick a listed size to change it.</p><p><img src="'+n+'" alt="Page setup dialog with Paper size, Orientation, and Margins in inches"></p><h2 id="change-margins" tabindex="-1">Change margins <a class="header-anchor" href="#change-margins" aria-label="Permalink to &quot;Change margins&quot;">​</a></h2><ol><li>Click <strong>Page setup</strong>.</li><li>Under <strong>Margins (inches)</strong>, enter <strong>Top</strong>, <strong>Bottom</strong>, <strong>Left</strong>, and <strong>Right</strong>.</li><li>Click <strong>Apply</strong>.</li></ol><p>Margins must be zero or more and leave room for text. If they don&#39;t, the dialog says so and <strong>Apply</strong> stays off.</p><h3 id="drag-margins-on-the-ruler" tabindex="-1">Drag margins on the ruler <a class="header-anchor" href="#drag-margins-on-the-ruler" aria-label="Permalink to &quot;Drag margins on the ruler&quot;">​</a></h3><p>Drag the edge of the shaded area on the ruler above the page to change the left or right margin. Drag the edge on the ruler at the left side to change the top or bottom margin.</p><h2 id="insert-a-page-break" tabindex="-1">Insert a page break <a class="header-anchor" href="#insert-a-page-break" aria-label="Permalink to &quot;Insert a page break&quot;">​</a></h2><ol><li>Put the cursor where the next page should start.</li><li>Press <code>⌘+Enter</code> / <code>Ctrl+Enter</code>.</li></ol><p>Everything after the cursor moves to the top of the next page. Long paragraphs and tables also flow onto the next page on their own.</p><h2 id="add-a-horizontal-line" tabindex="-1">Add a horizontal line <a class="header-anchor" href="#add-a-horizontal-line" aria-label="Permalink to &quot;Add a horizontal line&quot;">​</a></h2><ol><li>On an empty line in the body, type <code>---</code>.</li><li>Press <code>Enter</code>.</li></ol><p>A horizontal line replaces the three dashes, and the cursor moves to a new line below it.</p><h2 id="add-a-header-or-footer" tabindex="-1">Add a header or footer <a class="header-anchor" href="#add-a-header-or-footer" aria-label="Permalink to &quot;Add a header or footer&quot;">​</a></h2><ol><li>Double-click the top margin of any page for the header, or the bottom margin for the footer.</li><li>Type the text. The toolbar narrows to <strong>Font</strong>, <strong>Font size</strong>, <strong>Bold</strong>, <strong>Italic</strong>, <strong>Underline</strong>, colors, <strong>Text alignment</strong>, and <strong>Page number</strong>.</li><li>Press <code>Escape</code>, or click the page body, to go back to the body.</li></ol><p>The same header and footer appear on every page.</p><h2 id="add-page-numbers" tabindex="-1">Add page numbers <a class="header-anchor" href="#add-page-numbers" aria-label="Permalink to &quot;Add page numbers&quot;">​</a></h2><ol><li>Double-click the header or footer area to edit it.</li><li>Put the cursor where the number should go, and use <strong>Text alignment</strong> to place it left, center, or right.</li><li>Click <strong>Page number</strong> in the toolbar.</li></ol><p>Each page shows its own number, and the numbers update as pages are added or removed.</p><p><img src="'+s+'" alt="Footer in edit mode with the narrow footer toolbar and a centered page number"></p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar and select <strong>Page setup</strong> under <strong>Document</strong>. The ruler is hidden on a phone, so set margins in the dialog.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>There is one header and one footer for the whole document. You can&#39;t use a different first page.</li><li>You can&#39;t add a table or a page break to a header or footer. The narrow toolbar has no list, link, image, or style controls.</li><li>A table in the header or footer of an imported Word file is shown, and you can edit the text in its cells, but you can&#39;t add or remove its rows or columns.</li><li>Margins are set in inches, even when the ruler shows centimeters.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/lists-and-indents.html">Lists and indents</a> to indent paragraphs on the ruler.</li><li><a href="/docs/files/import-export.html">Import and export</a> to export the pages as PDF or Word.</li><li><a href="/docs/start/troubleshooting.html#margins-must-be-zero-or-a-positive-number-of-inches">Troubleshooting</a> for &quot;Margins must be zero or a positive number of inches.&quot;</li></ul>',30)])])}const f=a(i,[["render",l]]);export{m as __pageData,f as default};
